1864	    /// this returns an error associated with reading CSV data.
1865	    ///
1866	    /// Unlike `seek`, this will always cause an actual seek to be performed.
1867	    pub fn seek_raw(
1868	        &mut self,
1869	        seek_from: io::SeekFrom,
1870	        pos: Position,
1871	    ) -> Result<()> {
1872	        self.byte_headers()?;
1873	        self.state.seeked = true;
1874	        self.rdr.seek(seek_from)?;
1875	        self.core.reset();
1876	        // A BOM is only meaningful at the very start of the stream. Seeking
1877	        // to a non-zero record offset must preserve a BOM-like sequence there.
1878	        self.core.set_strip_bom(pos.byte() == 0);
1879	        self.core.set_line(pos.line());
1880	        self.state.cur_pos = pos;
1881	        self.state.eof = ReaderEofState::NotEof;
