        }
    }
    let res = self.dfa.new_read_record_result(
        state,
        false,
        nin >= input.len(),
        nout >= output.len(),
        nend >= ends.len(),
    );
    self.dfa_state = state;
    if res.is_record() {
        self.output_pos = 0;
    } else {
        self.output_pos += nout;
    }
    (res, nin, nout, nend)
}

