fn read_byte_record_resumable(&mut self, record: &mut ByteRecord) -> Result<bool> {
    use csv_core::ReadRecordResult::*;

    let mut partial = self.state.partial.take().unwrap_or_else(|| PartialRecord {
        pos: self.state.cur_pos.clone(),
        rec: ByteRecord::new(),
        outlen: 0,
        endlen: 0,
    });
