                Ok(input) => input,
                Err(err) => {
                    if err.kind() == io::ErrorKind::WouldBlock {
                        // Stash partial progress and hand the error back.
                        self.state.partial = Some(partial);
                        return Err(Error::from(err));
                    }
                    self.state.eof = ReaderEofState::IOError;
                    return Err(Error::from(err));
                }
            };
            let (fields, ends) = partial.rec.as_parts();
            self.core.read_record(input, &mut fields[partial.outlen..], &mut ends[partial.endlen..])
        };
        self.rdr.consume(nin);
        let byte = self.state.cur_pos.byte();
        self.state.cur_pos.set_byte(byte + nin as u64).set_line(self.core.line());
        partial.outlen += nout;
        partial.endlen += nend;
        match res {
            InputEmpty => continue,
            OutputFull => { partial.rec.expand_fields(); continue; }
            OutputEndsFull => { partial.rec.expand_ends(); continue; }
