fn core_marker_chunks_are_not_eof_or_empty_fields() {
    let marker = b"\xef\xbb\xbf";
    for nfa in [false, true] {
        for sizes in [vec![1, 1, 1], vec![1, 2], vec![2, 1], vec![3]] {
            let mut f = core(nfa, None);
            let mut r = core(nfa, None);
            let mut pos = 0;
            for size in sizes {
                let input = &marker[pos..pos + size];
                let (status, nin, nout) = f.read_field(input, &mut [0; 1]);
                assert_eq!(status, F::InputEmpty);
                assert_eq!((nin, nout), (size, 0));
                let (status, nin, nout, nend) = r.read_record(input, &mut [0; 1], &mut [0; 1]);
                assert_eq!(status, R::InputEmpty);
                assert_eq!((nin, nout, nend), (size, 0, 0));
                pos += size;
            }
            assert_eq!(field_rows(&mut f, BODY, &[BODY.len()], 1), ordinary_rows());
            assert_eq!(record_rows(&mut r, BODY, &[BODY.len()], 1), ordinary_rows());
