struct Fragmented { cursor: Cursor<Vec<u8>>, sizes: VecDeque<usize>, left: usize }
impl Fragmented {
    fn new(data: &[u8], sizes: Vec<usize>) -> Self {
        Self { cursor: Cursor::new(data.to_vec()), sizes: sizes.into(), left: 0 }
    }
}
impl Read for Fragmented {
    fn read(&mut self, output: &mut [u8]) -> io::Result<usize> {
        if output.is_empty() { return Ok(0); }
        if self.left == 0 { self.left = self.sizes.pop_front().unwrap_or(output.len()); }
        let cap = self.left.min(output.len());
        let n = self.cursor.read(&mut output[..cap])?;
        self.left -= n;
        Ok(n)
    }
}
fn fragmented(data: &[u8], sizes: Vec<usize>, cap: usize, headers: bool) -> csv::Reader<Fragmented> {
    csv::ReaderBuilder::new().has_headers(headers).buffer_capacity(cap).from_reader(Fragmented::new(data, sizes))
}

