/// Read a byte record from the underlying CSV reader, without accounting
/// for headers, resuming an interrupted record if necessary.
///
/// This is only used when `continue_on_would_block` is enabled...
#[inline(always)]
fn read_byte_record_resumable(&mut self, record: &mut ByteRecord) -> Result<bool> {
    use csv_core::ReadRecordResult::*;

    // Resume the record interrupted by a previous `WouldBlock` error, or
    // start a fresh one at the current position.
    let mut partial = self.state.partial.take().unwrap_or_else(|| {
        PartialRecord::new(self.state.cur_pos.clone())
    });
    // Until the record is complete, the caller's record stays empty and
    // points at the start of the record being read.
    record.set_position(Some(partial.pos.clone()));
    let result = self.read_record_resumable_impl(&mut partial);
    match result {
        // The record is complete: move it to the caller's record.
        Ok(true) => {
            std::mem::swap(record, &mut partial.rec);
            record.set_position(Some(partial.pos.clone()));
            self.state.add_record(record)?;
            Ok(true)
        }
        // The underlying reader hit end of file.
        Ok(false) => Ok(false),
        // Temporarily no data: stash progress and hand the error back.
        Err(err) if is_would_block(&err) => {
            self.state.partial = Some(partial);
            Err(err)
        }
        Err(err) => Err(err),
    }
}
```

