enum Action { Block, Deliver(usize) }
impl io::Read for ScriptedReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self.script.pop_front() {
            Some(Action::Block) => Err(io::Error::new(io::ErrorKind::WouldBlock, "would block")),
            Some(Action::Deliver(n)) => {
                let avail = &self.data[self.pos..];
                if avail.is_empty() { return Ok(0); }
                let n = n.min(avail.len()).min(buf.len());
                buf[..n].copy_from_slice(&avail[..n]);
                self.pos += n;
                Ok(n)
            }
            None => {
                // default: deliver everything remaining
                let avail = &self.data[self.pos..];
                let n = avail.len().min(buf.len());
                buf[..n].copy_from_slice(&avail[..n]);
                self.pos += n;
                Ok(n)
            }
        }
    }
}
