            if input_res.is_err() {
                self.state.eof = ReaderEofState::IOError;
            }
            let input = input_res?;
            let (fields, ends) = record.as_parts();
            self.core.read_record(
                input,
                &mut fields[outlen..],
                &mut ends[endlen..],
